{
  "claims": [
    {
      "claim": "The two phases an execution environment goes through when handling a Lambda request are the Init phase and the Invoke phase.",
      "label": "supported"
    },
    {
      "claim": "Init phase: This is the initialization phase where Lambda sets up the execution environment. During this phase, Lambda runs the code outside your main handler.",
      "label": "supported"
    },
    {
      "claim": "For subsequent requests, if the environment is already initialized, this phase is skipped.",
      "label": "supported"
    },
    {
      "claim": "Invoke phase: This is the phase where Lambda runs your function's main handler code to process the request.",
      "label": "supported"
    }
  ]
}
